      Paint()
        ..color = Colors.black87
        ..style = PaintingStyle.stroke
        ..strokeWidth = 3
        ..strokeCap = StrokeCap.round,
    );

    canvas.drawCircle(start, 5, Paint()..color = Colors.white);
    canvas.drawCircle(start, 3, Paint()..color = Colors.black87);

    final tip = point(1);
    final previous = point(0.99);
    final direction = (tip - previous) / (tip - previous).distance;
    final normal = Offset(-direction.dy, direction.dx);
    final base = tip - direction * 15;
    final arrow = Path()
      ..moveTo(tip.dx, tip.dy)
      ..lineTo((base + normal * 7).dx, (base + normal * 7).dy)
      ..lineTo((base - normal * 7).dx, (base - normal * 7).dy)
      ..close();
    canvas.drawPath(arrow, Paint()..color = Colors.black87);
    canvas.drawPath(
      arrow,
      Paint()
        ..color = Colors.white
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2,
    );
